import { suppletiveAdjunctTypeToIthkuil, } from "../adjunct/index.js";
import { affixToIthkuil } from "../affix/index.js";
import {} from "../ca/index.js";
import { caseToIthkuil, } from "../formative/index.js";
import { countVowelForms } from "../helpers/stress.js";
import { WithWYAlternative } from "../helpers/with-wy-alternative.js";
